"""Build the offline, double-clickable FX-Clover review desk v1.13."""

from __future__ import annotations

import json
from pathlib import Path

import pandas as pd


ROOT = Path(__file__).resolve().parent
OUTPUT = ROOT / "FX_Clover_Review_Desk_v1_13.html"


HTML = r'''<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FX-Clover Review Desk</title>
<style>:root{--ink:#17241f;--muted:#66736e;--paper:#f3f1e9;--card:#fffdf7;--line:#d7d8ce;--green:#176b4d;--amber:#d89a2b}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:"Yu Gothic UI","Hiragino Sans",Arial,sans-serif}button,input,select,textarea{font:inherit}.shell{width:min(1600px,100%);margin:auto;padding:24px 28px 56px}.top{display:flex;justify-content:space-between;align-items:end;gap:24px;border-bottom:3px solid var(--ink);padding-bottom:18px}.eye{margin:0 0 6px;color:var(--green);font-size:12px;font-weight:800;letter-spacing:.18em}h1{margin:0;font-size:clamp(26px,3vw,42px);line-height:1.05}.progress{min-width:230px;text-align:right;font-size:13px;font-weight:700}.track{height:7px;background:#d9ded7;margin-top:8px;border-radius:99px;overflow:hidden}.track i{display:block;height:100%;background:var(--green)}.notice{display:flex;gap:16px;margin:16px 0;padding:12px 16px;border-left:5px solid var(--amber);background:#fff4d9;font-size:13px}.toolbar{display:flex;align-items:center;gap:9px;margin:16px 0;flex-wrap:wrap}.toolbar button,.file{border:1px solid var(--line);background:var(--card);padding:10px 15px;border-radius:8px;font-weight:700;cursor:pointer}.toolbar .primary{margin-left:auto;background:var(--green);color:white}.file input{display:none}.counter{color:var(--muted);font-size:13px}.counter b{color:var(--ink);font-size:18px}.work{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(340px,.7fr);gap:18px;align-items:start}.card{background:var(--card);border:1px solid var(--line);border-radius:14px;box-shadow:0 8px 28px #2230290f;overflow:hidden}.meta{display:grid;grid-template-columns:.65fr .65fr 2fr .7fr;border-bottom:1px solid var(--line)}.meta div{padding:12px 15px;border-right:1px solid var(--line)}.meta span{display:block;color:var(--muted);font-size:10px;font-weight:800}.chart{width:100%;display:block;cursor:zoom-in}.caption{padding:10px 15px;color:var(--muted);font-size:12px}.form{padding:20px;position:sticky;top:14px}.form h2{margin:0 0 16px}.form h3{margin:18px 0 10px;padding-top:14px;border-top:1px solid var(--line);font-size:14px}.form label{display:grid;gap:5px;margin-bottom:11px;color:#45524d;font-size:12px;font-weight:750}.form input,.form select,.form textarea{width:100%;padding:9px 10px;border:1px solid #c9cdc6;border-radius:7px;background:white}.two,.checks{display:grid;grid-template-columns:1fr 1fr;gap:0 10px}.saved{padding:9px;background:#e5f2eb;color:var(--green);border-radius:7px;text-align:center;font-size:12px;font-weight:700}.lightbox{display:none;position:fixed;inset:0;z-index:9;background:#080e0beb;place-items:center;padding:22px}.lightbox.open{display:grid}.lightbox img{max-width:96vw;max-height:92vh}.lightbox button{position:fixed;right:22px;top:14px;border:0;background:none;color:white;font-size:38px}@media(max-width:980px){.shell{padding:18px 14px}.top{align-items:start;flex-direction:column}.progress{min-width:100%;text-align:left}.work{grid-template-columns:1fr}.form{position:static}.toolbar .primary{margin-left:0}}@media(max-width:560px){.notice{flex-direction:column;gap:4px}.meta{grid-template-columns:1fr 1fr}.two,.checks{grid-template-columns:1fr}.toolbar button,.file{flex:1;text-align:center}.counter{width:100%;text-align:center;order:-1}}</style></head>
<body><main class="shell"><header class="top"><div><p class="eye">FX-CLOVER / BLIND REVIEW</p><h1>ポコニカル候補 レビューデスク</h1></div><div class="progress"><span id="progressText">0 / 60 判定済み</span><div class="track"><i id="progressBar"></i></div></div></header>
<section class="notice"><strong>手動判定専用</strong><span>研究予測は非表示です。不明な項目は空欄のままにしてください。入力内容を公式ルールへ自動昇格しません。</span></section>
<nav class="toolbar"><button id="prev">← 前へ</button><div class="counter">候補 <b id="number">1</b> / 60</div><button id="next">次へ →</button><button id="unreviewed">次の未判定</button><label class="file">CSV読込<input id="import" type="file" accept=".csv"></label><button id="export" class="primary">CSVを書き出す</button></nav>
<section class="work"><article class="card"><div class="meta"><div><span>通貨</span><b id="symbol"></b></div><div><span>足</span><b id="tf"></b></div><div><span>候補時刻</span><b id="time"></b></div><div><span>状態</span><b id="state"></b></div></div><img id="chart" class="chart" alt="H1およびM15チャート"><p class="caption">候補足は右端です。候補後の未来足は表示していません。画像を押すと拡大します。</p></article>
<aside class="card form"><h2>手動判定</h2><label>最終判定<select data-f="manual_decision"><option value="">未入力</option><option>FINAL_SHAPE_CANDIDATE</option><option>HOLD</option><option>EXCLUDED_SHAPE</option><option>UNDETERMINED</option></select></label><label>フォーメーション<select data-f="formation_type"><option value="">未入力</option><option>DOUBLE_TOP</option><option>HEAD_AND_SHOULDERS</option><option>UNDETERMINED</option></select></label><div class="two"><label>ストップ根拠<select data-f="stop_anchor_type"><option value="">未入力</option><option>LEFT_SHOULDER</option><option>CENTRAL_TOP</option><option>UNDETERMINED</option></select></label><label>ストップ価格<input data-f="stop_anchor_price" placeholder="不明なら空欄"></label></div><label>ストップ時刻<input data-f="stop_anchor_time" placeholder="YYYY-MM-DD HH:MM"></label><h3>裁量確認</h3><div id="checks" class="checks"></div><label>レビュー担当<input data-f="reviewer" placeholder="任意"></label><label>メモ<textarea data-f="review_note" rows="4" placeholder="判断根拠や未確定点"></textarea></label><div class="saved">入力はこの端末へ自動保存されます</div></aside></section></main>
<div id="lightbox" class="lightbox"><button>×</button><img id="zoom"></div>
<script>const candidates=__CANDIDATES__;const fields=__FIELDS__;const bools=[["mid_range","中段レンジ"],["lower_right_shoulder","右肩が低い"],["inside_dma25x5","DMA25x5内側"],["ma_path_clear","障害MAなし"],["has_room","下方向の伸びしろ"],["upper_environment_valid","上位環境有効"]];const key="fx-clover-review-v1-13";let pos=0,reviews={};try{reviews=JSON.parse(localStorage.getItem(key)||"{}")}catch{}const blank=()=>Object.fromEntries(fields.map(x=>[x,""]));const byId=id=>document.getElementById(id);const number=byId("number"),symbol=byId("symbol"),tf=byId("tf"),time=byId("time"),state=byId("state"),chart=byId("chart"),zoom=byId("zoom"),prev=byId("prev"),next=byId("next"),unreviewed=byId("unreviewed"),lightbox=byId("lightbox"),progressText=byId("progressText"),progressBar=byId("progressBar"),exportBtn=byId("export");
const checks=document.getElementById("checks");bools.forEach(([f,l])=>{const el=document.createElement("label");el.textContent=l;el.innerHTML+=`<select data-f="${f}"><option value="">未入力</option><option>TRUE</option><option>FALSE</option><option>UNDETERMINED</option></select>`;checks.appendChild(el)});const inputs=[...document.querySelectorAll("[data-f]")];
function save(){localStorage.setItem(key,JSON.stringify(reviews));updateProgress()}function currentReview(){return reviews[candidates[pos].candidate_key]||blank()}function render(){const c=candidates[pos],r=currentReview();number.textContent=pos+1;symbol.textContent=c.symbol;tf.textContent=c.timeframe;time.textContent=c.timestamp.replace("T"," ");state.textContent=c.state;chart.src=c.image;zoom.src=c.image;inputs.forEach(x=>x.value=r[x.dataset.f]||"");prev.disabled=pos===0;next.disabled=pos===candidates.length-1;updateProgress();scrollTo({top:0,behavior:"smooth"})}function updateProgress(){const n=candidates.filter(c=>{const r=reviews[c.candidate_key]||{};return !!r.manual_decision||r.review_status==="REVIEWED"}).length;progressText.textContent=`${n} / ${candidates.length} 判定済み`;progressBar.style.width=`${n/candidates.length*100}%`}
inputs.forEach(el=>el.addEventListener("input",()=>{const c=candidates[pos],r={...blank(),...(reviews[c.candidate_key]||{})};r[el.dataset.f]=el.value;if(el.dataset.f==="manual_decision")r.review_status=el.value?"REVIEWED":"UNREVIEWED";reviews[c.candidate_key]=r;save()}));prev.onclick=()=>{pos=Math.max(0,pos-1);render()};next.onclick=()=>{pos=Math.min(candidates.length-1,pos+1);render()};unreviewed.onclick=()=>{let n=candidates.findIndex((c,i)=>i>pos&&!(reviews[c.candidate_key]||{}).manual_decision);if(n<0)n=candidates.findIndex(c=>!(reviews[c.candidate_key]||{}).manual_decision);if(n>=0){pos=n;render()}};
chart.onclick=()=>lightbox.classList.add("open");lightbox.onclick=()=>lightbox.classList.remove("open");function esc(v){v=String(v??"");return /[",\n]/.test(v)?`"${v.replaceAll('"','""')}"`:v}exportBtn.onclick=()=>{const hs=["candidate_key","symbol","timeframe","timestamp","state",...fields,"classification"],lines=[hs.join(",")];candidates.forEach(c=>{const v={...c,...(reviews[c.candidate_key]||blank()),classification:"MANUAL_INPUT_REQUIRED"};lines.push(hs.map(h=>esc(v[h])).join(","))});const b=new Blob(["\ufeff"+lines.join("\r\n")],{type:"text/csv"}),u=URL.createObjectURL(b),a=document.createElement("a");a.href=u;a.download="GBPJPY_blind_review_input_v1_13.csv";a.click();URL.revokeObjectURL(u)};
function parse(t){let rs=[],r=[],v="",q=false;for(let i=0;i<t.length;i++){const c=t[i];if(q){if(c==='"'&&t[i+1]==='"'){v+='"';i++}else if(c==='"')q=false;else v+=c}else if(c==='"')q=true;else if(c===","){r.push(v);v=""}else if(c==="\n"){r.push(v.replace(/\r$/,"") );rs.push(r);r=[];v=""}else v+=c}if(v||r.length){r.push(v);rs.push(r)}return rs}document.getElementById("import").onchange=e=>{const f=e.target.files[0];if(!f)return;f.text().then(t=>{const rs=parse(t),h=rs[0],ki=h.indexOf("candidate_key");rs.slice(1).forEach(row=>{const k=row[ki];if(!k)return;const r=blank();fields.forEach(x=>{const i=h.indexOf(x);if(i>=0)r[x]=row[i]||""});reviews[k]=r});save();render()});e.target.value=""};render();</script></body></html>'''


def run() -> None:
    frame = pd.read_csv(ROOT / "GBPJPY_blind_review_input_v1_12.csv", keep_default_na=False)
    candidates = []
    for index, row in enumerate(frame.itertuples(index=False), start=1):
        candidates.append({
            "index": index, "candidate_key": row.candidate_key,
            "symbol": row.symbol, "timeframe": row.timeframe,
            "timestamp": row.timestamp, "state": row.state,
            "image": f"review_desk_assets/candidate-{index:02d}.png",
        })
    manual_fields = [
        "manual_decision", "formation_type", "stop_anchor_type", "stop_anchor_time",
        "stop_anchor_price", "mid_range", "lower_right_shoulder", "inside_dma25x5",
        "ma_path_clear", "has_room", "upper_environment_valid", "review_status",
        "review_note", "reviewer",
    ]
    output = HTML.replace("__CANDIDATES__", json.dumps(candidates, ensure_ascii=False))
    output = output.replace("__FIELDS__", json.dumps(manual_fields, ensure_ascii=False))
    OUTPUT.write_text(output, encoding="utf-8")
    print({"output": str(OUTPUT), "candidates": len(candidates), "orders_enabled": False})


if __name__ == "__main__":
    run()
